function render(){ctx.save();if(shake>.2)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawBackground();ctx.save();ctx.translate(-camera,0);drawWorld();ctx.restore();drawForeground();if(screenFlash>.01){ctx.fillStyle=`rgba(190,255,255,${screenFlash})`;ctx.fillRect(0,0,W,H)}ctx.restore();}
function drawBackground(){let zone=zones[0];for(const z of zones)if(player.x>z.x)zone=z;const grd=ctx.createLinearGradient(0,0,0,H);grd.addColorStop(0,zone.sky);grd.addColorStop(.55,'#101d27');grd.addColorStop(1,'#111720');ctx.fillStyle=grd;ctx.fillRect(0,0,W,H);
// distant orbital ring and diffuse moon
ctx.save();ctx.globalAlpha=.27;ctx.strokeStyle=zone.glow;ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(670,95,290,43,-.14,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=.12;ctx.fillStyle=zone.glow;ctx.beginPath();ctx.arc(756,107,68,0,Math.PI*2);ctx.fill();ctx.restore();
// layered ruined skyline
for(let layer=0;layer<3;layer++){let par=[.1,.22,.38][layer],bw=84+layer*38,off=-(camera*par)%bw;ctx.globalAlpha=[.3,.48,.72][layer];for(let i=-1;i<14;i++){let x=i*bw+off,h=105+((i*37+layer*89)%130+130)%130;ctx.fillStyle=layer===2?'#101b23':layer===1?'#0c1820':'#09141c';ctx.fillRect(x,360-h,bw-6,h+185);ctx.fillStyle=zone.glow;ctx.globalAlpha=.12;for(let wy=385-h;wy<450;wy+=19)for(let wx=x+12;wx<x+bw-15;wx+=21)if(((wx+wy+i)%4)<2)ctx.fillRect(wx,wy,3,7);ctx.globalAlpha=[.3,.48,.72][layer];ctx.fillStyle='#192a32';ctx.fillRect(x+4,360-h,bw-15,3);if(layer===2){ctx.strokeStyle='#344a50';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+bw-17,360-h);ctx.lineTo(x+bw-17,360-h-24);ctx.stroke()}}}ctx.globalAlpha=1;
// distant terrain glow / data sea
const fog=ctx.createLinearGradient(0,390,0,525);fog.addColorStop(0,'#2fd5c31a');fog.addColorStop(1,'#06101b00');ctx.fillStyle=fog;ctx.fillRect(0,390,W,150);
// rain streaks
ctx.strokeStyle='#82d5d633';ctx.lineWidth=1;for(let i=0;i<95;i++){let x=(i*137+frame*2.7)%W,y=(i*83+frame*6.2)%H;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y+11);ctx.stroke()}
if(zone===zones[1]){ctx.save();for(let i=0;i<10;i++){let x=((i*167-camera*.17)%1100+1100)%1100-70;ctx.strokeStyle='#50d17b35';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x,470);ctx.bezierCurveTo(x+20,390,x-15,300,x+8,205+i%3*20);ctx.stroke();for(let j=0;j<4;j++){ctx.fillStyle=j%2?'#69fb9738':'#c3ff7040';ctx.beginPath();ctx.ellipse(x+(j%2?25:-19),280+j*37,16,6,(j%2?-.6:.6),0,Math.PI*2);ctx.fill()}}ctx.restore()}
if(zone===zones[2]){ctx.save();for(let i=0;i<6;i++){let x=((i*220-camera*.2)%1150+1150)%1150-50;ctx.fillStyle='#35234166';ctx.beginPath();ctx.moveTo(x-70,356);ctx.lineTo(x-48,190);ctx.lineTo(x,135);ctx.lineTo(x+48,190);ctx.lineTo(x+70,356);ctx.closePath();ctx.fill();ctx.strokeStyle='#ed4b9d66';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#a3348055';ctx.fillRect(x-30,210,60,130);ctx.strokeStyle='#ff78c966';ctx.beginPath();ctx.moveTo(x,190);ctx.lineTo(x,340);ctx.moveTo(x-35,260);ctx.lineTo(x+35,260);ctx.stroke()}ctx.restore()}}
function drawWorld(){const z=zones.findLast(v=>player.x>v.x)||zones[0];
// floor platform area, architecture
for(const q of platforms){if(q.x+q.w<camera-30||q.x>camera+W+30)continue;if(q.type==='hazard'){ctx.fillStyle='#101419';ctx.fillRect(q.x,q.y,q.w,q.h);ctx.fillStyle='#ff3e8b';ctx.shadowColor='#ff2984';ctx.shadowBlur=14;for(let i=0;i<q.w;i+=16){ctx.fillRect(q.x+i,q.y+4+Math.sin(frame*.2+i)*3,8,2)}ctx.shadowBlur=0;continue}ctx.fillStyle=q.type==='metal'?'#17232b':'#1c2a30';ctx.fillRect(q.x,q.y,q.w,q.h);ctx.fillStyle='#41555b';ctx.fillRect(q.x,q.y,q.w,4);ctx.fillStyle='#25343b';for(let x=q.x+9;x<q.x+q.w-8;x+=28){ctx.fillRect(x,q.y+12,2,6);ctx.fillStyle='#617980';ctx.fillRect(x+5,q.y+11,2,2);ctx.fillStyle='#25343b'}if(q.y===floorY){ctx.fillStyle='#13222b';ctx.fillRect(q.x,q.y+12,q.w,3);for(let x=q.x+16;x<q.x+q.w;x+=85){ctx.fillStyle='#35464b';ctx.fillRect(x,q.y+22,21,2);ctx.fillStyle='#25343b';ctx.fillRect(x+8,q.y+24,2,15)}ctx.fillStyle='#24bfae35';ctx.fillRect(q.x,q.y-3,q.w,2)}}
// floor puddle reflections
for(let i=Math.floor((camera-100)/150);i<(camera+W)/150+1;i++){let x=i*150+45;ctx.fillStyle='#32d8cf1c';ctx.beginPath();ctx.ellipse(x,465,32,2,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ff3c8b33';ctx.fillRect(x+12,462,8,1)}
// cable tubes and biomechanical growth
for(let i=Math.floor(camera/310);i<(camera+W)/310+1;i++){let x=i*310+260;ctx.strokeStyle='#243a40';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(x,468);ctx.bezierCurveTo(x-24,425,x+30,414,x+4,370);ctx.stroke();ctx.strokeStyle=z===zones[1]?'#8cff6755':'#43dacc44';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,467);ctx.bezierCurveTo(x-24,425,x+30,414,x+4,370);ctx.stroke();ctx.fillStyle='#33474b';ctx.fillRect(x-7,407,13,5)}
// terminal beacons
for(const t of terminals){if(t.x<camera-50||t.x>camera+W+50)continue;ctx.fillStyle='#15252d';ctx.fillRect(t.x-12,t.y-34,24,36);ctx.fillStyle=t.used?'#667379':'#50ead4';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=14;ctx.fillRect(t.x-7,t.y-29,14,9);ctx.shadowBlur=0;ctx.fillStyle='#82989c';ctx.fillRect(t.x-15,t.y,30,4);if(Math.abs(t.x-player.x)<110&&!t.used){ctx.font='9px monospace';ctx.fillStyle='#8ff8e9';ctx.fillText('[ E ]',t.x-13,t.y-42)}}
// grapple anchor rings
for(const a of anchors){if(a.x<camera-30||a.x>camera+W+30)continue;ctx.strokeStyle='#55dbc755';ctx.lineWidth=1;ctx.beginPath();ctx.arc(a.x,a.y,9+Math.sin(frame*.08+a.x)*2,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#74fff2';ctx.fillRect(a.x-2,a.y-2,4,4)}
for(const q of pickups)if(!q.got)drawPickup(q);
for(const e of enemies)if(!e.dead)drawEnemy(e);
if(boss&&boss.state!=='sleep'&&boss.hp>0)drawBoss();
for(const q of projectiles)drawProjectile(q);
for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size);ctx.globalAlpha=1}
if(player.hook){ctx.strokeStyle='#83fff0';ctx.lineWidth=2;ctx.shadowColor='#4df5e5';ctx.shadowBlur=8;ctx.beginPath();ctx.moveTo(player.x+14,player.y+13);ctx.lineTo(player.hook.x,player.hook.y);ctx.stroke();ctx.shadowBlur=0}
drawPlayer();
if(boss&&boss.state!=='sleep'&&boss.hp>0){ctx.fillStyle='#091016dd';ctx.fillRect(300,78,360,13);ctx.fillStyle='#fa3b91';ctx.fillRect(302,80,356*(boss.hp/boss.maxHp),9);ctx.strokeStyle='#ffc1dd88';ctx.strokeRect(300,78,360,13);ctx.fillStyle='#ff9bc7';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText('S I N E  /  H I V E  M I N D',480,69);ctx.textAlign='left'}
}
function drawPickup(q){let bob=Math.sin(frame*.08+q.x)*5,x=q.x,y=q.y+bob;ctx.save();ctx.shadowBlur=20;ctx.shadowColor=q.type==='memory'?'#ffcf74':q.type==='double'?'#5df5e3':q.type==='thermal'?'#ff693e':q.type==='cloak'?'#cb69ff':'#8aff86';let c=q.type==='memory'?'#ffdc8d':q.type==='double'?'#79fff0':q.type==='thermal'?'#ff754a':q.type==='cloak'?'#d57bff':'#9aff91';ctx.fillStyle=c;ctx.translate(x,y);if(q.type==='memory'){ctx.rotate(Math.PI/4);ctx.fillRect(-8,-8,16,16);ctx.fillStyle='#fff5cf';ctx.fillRect(-3,-3,6,6)}else{ctx.beginPath();ctx.arc(0,0,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#0c1920';ctx.font='bold 11px monospace';ctx.textAlign='center';ctx.fillText(({double:'Ⅱ',thermal:'T',cloak:'◉',heal:'+',cell:'ϟ'})[q.type]||'◇',0,4)}ctx.restore();ctx.strokeStyle=c+'66';ctx.beginPath();ctx.ellipse(x,y+13,17,4,0,0,Math.PI*2);ctx.stroke()}
function drawEnemy(e){ctx.save();if(e.flash)ctx.globalAlpha=.48;const cx=e.x+e.w/2,cy=e.y+e.h/2;ctx.shadowBlur=12;ctx.shadowColor=e.type==='vine'?'#96ff55':'#ff3488';if(e.type==='drone'){ctx.fillStyle='#283941';ctx.beginPath();ctx.moveTo(cx-e.w/2,cy);ctx.lineTo(cx-10,cy-15);ctx.lineTo(cx+12,cy-13);ctx.lineTo(cx+e.w/2,cy);ctx.lineTo(cx+12,cy+13);ctx.lineTo(cx-12,cy+14);ctx.closePath();ctx.fill();ctx.fillStyle='#ff4d9b';ctx.fillRect(cx-4,cy-3,11,5);ctx.fillStyle='#96a9aa';ctx.fillRect(cx-23,cy-2,8,4);ctx.fillRect(cx+15,cy-2,8,4)}else if(e.type==='vine'){ctx.fillStyle='#22382c';ctx.beginPath();ctx.ellipse(cx,cy,14,24,Math.sin(frame*.04)*.15,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#78db54';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(cx,cy+20);ctx.quadraticCurveTo(cx-24,cy+3,cx-18,cy-18);ctx.moveTo(cx+1,cy+8);ctx.quadraticCurveTo(cx+25,cy-4,cx+17,cy-22);ctx.stroke();ctx.fillStyle='#c9ff6c';ctx.fillRect(cx-5,cy-10,10,4)}else{ctx.fillStyle=e.type==='cultist'?'#30233c':'#242f39';ctx.fillRect(cx-11,cy-22,22,32);ctx.fillStyle='#0b1319';ctx.beginPath();ctx.arc(cx,cy-27,10,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.type==='cultist'?'#ff54b2':'#ff557e';ctx.fillRect(cx-5,cy-29,11,3);ctx.fillStyle='#86979a';ctx.fillRect(cx-17,cy-18,6,21);ctx.fillStyle='#35464c';ctx.fillRect(cx-10,cy+10,7,18);ctx.fillRect(cx+4,cy+10,7,18);if(e.type==='cultist'){ctx.strokeStyle='#fa48aa';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cx+10,cy-12);ctx.lineTo(cx+21,cy-29);ctx.stroke()}}ctx.shadowBlur=0;ctx.globalAlpha=1;ctx.fillStyle='#131b21';ctx.fillRect(e.x,e.y-9,e.w,3);ctx.fillStyle='#ff4d8c';ctx.fillRect(e.x,e.y-9,e.w*Math.max(0,e.hp/e.maxHp),3);ctx.restore()}
function drawProjectile(q){ctx.save();ctx.fillStyle=q.color;ctx.shadowColor=q.color;ctx.shadowBlur=15;ctx.beginPath();ctx.ellipse(q.x,q.y, q.team==='player'?10:7,4,Math.atan2(q.vy,q.vx),0,Math.PI*2);ctx.fill();ctx.restore()}

function drawPlayer(){const p=player;if(!running&&p.x===100){p.y= floorY-p.h}ctx.save();if(p.invuln>0&&frame%6<3)ctx.globalAlpha=.44;let cx=p.x+p.w/2,top=p.y,lean=Math.max(-.2,Math.min(.2,p.vx*.035));ctx.translate(cx,top);ctx.scale(p.face,1);ctx.rotate(lean);if(p.cloak){ctx.globalAlpha*=.45}
// long synthetic hair strands, flowing with velocity
ctx.strokeStyle='#c8e1e4';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-2,8);ctx.quadraticCurveTo(-15,22,-12-p.vx*1.1,43);ctx.moveTo(2,7);ctx.quadraticCurveTo(16,23,11-p.vx*1.3,39);ctx.stroke();ctx.strokeStyle='#7798a4';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-5,9);ctx.quadraticCurveTo(-18,24,-15-p.vx,38);ctx.stroke();
// legs, tactical suit
let stride=p.onGround?Math.sin(frame*.22+Math.abs(p.x)*.02)*Math.min(7,Math.abs(p.vx)*1.6):2;ctx.strokeStyle='#a7c0c5';ctx.lineWidth=6;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-5,43);ctx.lineTo(-7+stride,58);ctx.moveTo(5,43);ctx.lineTo(7-stride,58);ctx.stroke();ctx.strokeStyle='#38d9cb';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-7+stride,58);ctx.lineTo(-1+stride,59);ctx.moveTo(7-stride,58);ctx.lineTo(13-stride,59);ctx.stroke();
ctx.fillStyle='#19262e';ctx.beginPath();ctx.moveTo(-9,18);ctx.lineTo(9,18);ctx.lineTo(11,43);ctx.lineTo(0,49);ctx.lineTo(-11,43);ctx.closePath();ctx.fill();ctx.strokeStyle='#718c94';ctx.lineWidth=1.5;ctx.stroke();ctx.fillStyle='#44e4d7';ctx.fillRect(-2,25,4,10);ctx.fillStyle='#b8ccd0';ctx.fillRect(-8,37,16,2);
// shoulders/arms and gauntlet
ctx.fillStyle='#b3c9ce';ctx.fillRect(-12,19,6,9);ctx.fillStyle='#26363f';ctx.fillRect(7,20,6,17);ctx.fillStyle='#4cf2df';ctx.fillRect(8,27,4,3);
// neck and face
ctx.fillStyle='#cadbdd';ctx.fillRect(-4,8,8,9);ctx.fillStyle='#d5e4e6';ctx.beginPath();ctx.ellipse(0,1,9,12,.06,0,Math.PI*2);ctx.fill();ctx.fillStyle='#24353d';ctx.beginPath();ctx.moveTo(-10,-5);ctx.quadraticCurveTo(-9,-16,1,-14);ctx.quadraticCurveTo(12,-13,10,-3);ctx.lineTo(7,-2);ctx.lineTo(4,-8);ctx.lineTo(-4,-6);ctx.closePath();ctx.fill();ctx.fillStyle='#55f1e4';ctx.fillRect(3,0,5,2);ctx.fillStyle='#e7f2ef';ctx.fillRect(-1,4,5,1);
// blade and active plasma slash
if(p.attack>0||!running){ctx.save();ctx.translate(9,28);let a=p.attack>0?-.8+(13-p.attack)*.14:-.55;ctx.rotate(a);ctx.shadowBlur=15;ctx.shadowColor='#69fff2';ctx.strokeStyle='#b8fff6';ctx.lineWidth=p.attack>0?5:3;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(43,0);ctx.stroke();ctx.strokeStyle='#24dccd';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-3);ctx.lineTo(32,-3);ctx.stroke();ctx.fillStyle='#ecffff';ctx.fillRect(0,-3,8,6);if(p.attack>0){ctx.strokeStyle='#6bfff1aa';ctx.lineWidth=2;ctx.beginPath();ctx.arc(4,4,43,-.85,.85);ctx.stroke()}ctx.restore()}
if(p.parry>0){ctx.strokeStyle='#c3ffff';ctx.lineWidth=2;ctx.shadowColor='#73fff3';ctx.shadowBlur=18;ctx.beginPath();ctx.arc(7,28,30,-1.2,1.2);ctx.stroke();ctx.fillStyle='#caffff';ctx.fillRect(18,20,4,4)}ctx.restore();}
function drawBoss(){const b=boss;ctx.save();let cx=b.x,cy=b.y;if(b.flash)ctx.globalAlpha=.5;ctx.shadowBlur=28;ctx.shadowColor='#fa3295';// robe silhouette
ctx.fillStyle='#291a31';ctx.beginPath();ctx.moveTo(cx-30,cy+19);ctx.lineTo(cx-43,cy+105);ctx.lineTo(cx-61,cy+118);ctx.lineTo(cx+61,cy+118);ctx.lineTo(cx+43,cy+105);ctx.lineTo(cx+30,cy+19);ctx.closePath();ctx.fill();ctx.strokeStyle='#8c3d79';ctx.lineWidth=2;ctx.stroke();
// skeletal arms
ctx.strokeStyle='#9e6d9c';ctx.lineWidth=9;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(cx-27,cy+36);ctx.lineTo(cx-54,cy+67);ctx.moveTo(cx+27,cy+36);ctx.lineTo(cx+54,cy+67);ctx.stroke();ctx.strokeStyle='#ff459f';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(cx-53,cy+65);ctx.lineTo(cx-64,cy+83);ctx.moveTo(cx+53,cy+65);ctx.lineTo(cx+64,cy+83);ctx.stroke();
// mask/head
ctx.fillStyle='#54405a';ctx.beginPath();ctx.arc(cx,cy+18,24,Math.PI,0);ctx.lineTo(cx+20,cy+43);ctx.lineTo(cx,cy+53);ctx.lineTo(cx-20,cy+43);ctx.closePath();ctx.fill();ctx.fillStyle='#fa54ac';ctx.fillRect(cx-14,cy+15,28,4);ctx.fillStyle='#fff0fb';ctx.fillRect(cx-8,cy+15,5,3);ctx.fillRect(cx+4,cy+15,5,3);ctx.fillStyle='#efb1d8';ctx.fillRect(cx-3,cy+45,6,20);ctx.strokeStyle='#ed72be';ctx.lineWidth=1;for(let i=-2;i<=2;i++){ctx.beginPath();ctx.moveTo(cx+i*9,cy+82);ctx.lineTo(cx+i*14,cy+110);ctx.stroke()}ctx.shadowBlur=0;ctx.restore()}
function drawForeground(){// wet floor reflections / edge vignette
ctx.save();let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#00000022');g.addColorStop(.72,'#00000000');g.addColorStop(1,'#00000088');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);let v=ctx.createRadialGradient(W/2,H/2,160,W/2,H/2,590);v.addColorStop(.55,'#00000000');v.addColorStop(1,'#02060bc9');ctx.fillStyle=v;ctx.fillRect(0,0,W,H);
// crosshair hints when near interactables
if(running){ctx.globalAlpha=.45;ctx.fillStyle='#75f8e5';ctx.font='9px monospace';if(player.x<340)ctx.fillText('E  /  LER FRAGMENTO',player.x-camera+35,player.y-15);ctx.globalAlpha=1}
ctx.restore()}
updateHud();render();
})();
</script></body></html>

