function damageEnemy(e,n){e.hp-=n;e.flash=8;flash=.07;shake=2;sfx(125,.06,'square',.025);if(e.hp<=0)e.dead=true}
function hurt(n){if(p.inv||p.win)return;p.hp-=n;p.inv=48;p.stun=8;p.vx=-p.face*4.5;p.vy=-4;shake=8;flash=.22;sfx(90,.2,'sawtooth',.06);emit(p.x+14,p.y+28,'#ff477f',12);if(p.hp<=0)respawn()}
function respawn(){deadCount++;p.hp=70;p.energy=60;p.x=checkpoint?checkpoint:100;p.y=fy-p.h;p.vx=p.vy=0;p.inv=90;p.hook=null;p.dash=0;cam=Math.max(0,p.x-W*.38);shots=shots.filter(s=>s.team==='p');notify('RECONSTRUÇÃO '+deadCount,'Sua forma retorna. A memória, não.');}
function bossUpdate(){if(!boss||boss.hp<=0)return;let dx=p.x-boss.x;if(boss.state==='sleep'&&p.x>4650){if(memories<3){boss.x=4780;notify('SELO DE MEMÓRIA','Sine exige os três fragmentos para abrir a catedral.');p.x=Math.min(p.x,4700)}else{boss.state='awake';boss.cd=55;notify('SINE // NÚCLEO DESPERTO','Você trouxe o passado até mim.');sfx(55,.8,'sawtooth',.08)}}if(boss.state==='sleep')return;if(boss.flash)boss.flash--;if(boss.stun)boss.stun--;if(boss.cd)boss.cd--;boss.y=350+Math.sin(frame/34)*17;if(!boss.stun&&!boss.cd){boss.cd=92+Math.random()*35;let n=boss.hp<boss.max*.4?3:2;for(let i=0;i<n;i++){let aim=Math.sign(p.x-boss.x)||-1;shots.push({x:boss.x+boss.w/2,y:boss.y+50+(i-(n-1)/2)*15,vx:aim*(3.1+(boss.max-boss.hp)/260),vy:(i-(n-1)/2)*1.3,team:'e',life:180,dmg:12,col:'#ff4d9c'})}if(boss.hp<boss.max*.48&&Math.abs(dx)<260){boss.x=Math.max(4680,Math.min(5000,boss.x+Math.sign(dx)*70));shake=3}sfx(120,.15,'triangle',.04)}if(boss.hp<=0)win()}
function shotUpdate(){for(const s of shots){s.x+=s.vx;s.y+=(s.vy||0);s.life--;if(s.team==='p'){for(const e of foes){if(!e.dead&&s.x>e.x&&s.x<e.x+e.w&&s.y>e.y&&s.y<e.y+e.h){damageEnemy(e,s.dmg||37);s.life=0;emit(s.x,s.y,s.col,5)}}if(boss.state!=='sleep'&&s.x>boss.x&&s.x<boss.x+boss.w&&s.y>boss.y&&s.y<boss.y+boss.h){boss.hp-=s.dmg||37;boss.flash=7;s.life=0}}else if(s.x>p.x&&s.x<p.x+p.w&&s.y>p.y&&s.y<p.y+p.h){if(p.parry){s.life=0;p.energy=Math.min(100,p.energy+12);emit(s.x,s.y,'#bfffff',8);sfx(850,.08,'sine',.04)}else{hurt(s.dmg||10);s.life=0}}}shots=shots.filter(s=>s.life>0&&s.x>-50&&s.x<WW+50);}
function pickupUpdate(){for(const q of loot){if(q.got||Math.abs(q.x-(p.x+14))>30||Math.abs(q.y-(p.y+30))>45)continue;if(q.t==='memory'){q.got=true;memories++;p.energy=100;checkpoint=q.x<1700?100:q.x<3400?1740:3430;notify('FRAGMENTO RECUPERADO','Memória intacta '+memories+' / 3 · checkpoint sincronizado');dialog('MEMÓRIA '+memories+' // ARQUIVO HUMANO',memories===1?'Uma mão pequena segurava a minha. Não consigo lembrar o rosto.':memories===2?'A estação cantava antes de aprender a gritar.':'Não era uma ordem para sobreviver. Era um pedido para lembrar.');emit(q.x,q.y,'#ffcf74',18);sfx(720,.28,'sine',.06)}else{q.got=true;if(q.t==='double'){p.double=true;ui('ability').textContent='SALTO DUPLO　/　PHASE-DASH';notify('MÓDULO INSTALADO','Salto duplo: pressione espaço no ar.')}if(q.t==='thermal'){p.thermal=true;notify('VISÃO TÉRMICA','Inimigos e caminhos revelados no escuro.')}if(q.t==='cloak'){p.cloak=true;notify('MANTO DE FASE','Dash ampliado. Integridade restaurada.');p.hp=100}if(q.t==='heal'){p.hp=Math.min(100,p.hp+35);p.energy=Math.min(100,p.energy+24);notify('NANITES ABSORVIDOS','Integridade parcialmente restaurada.')}if(q.t==='cell'){p.energy=100;notify('CÉLULA DE NÚCLEO','Energia recarregada.')}sfx(600,.15,'triangle',.04);emit(q.x,q.y,'#62f5e3',9)}}}
function particlesUpdate(){for(const a of sparks){a.x+=a.vx;a.y+=a.vy;a.vy+=.06;a.life--;a.vx*=.98}sparks=sparks.filter(a=>a.life>0);if(sparks.length>240)sparks.splice(0,sparks.length-240)}
function emit(x0,y0,col,n){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,v=Math.random()*3+1;sparks.push({x:x0,y:y0,vx:Math.cos(a)*v,vy:Math.sin(a)*v-1,col,life:18+Math.random()*24})}}
function notify(a,b){ui('toast').querySelector('strong').textContent=a;ui('toast').querySelector('span').textContent=b;ui('toast').classList.add('show');toastTime=210}
function dialog(a,b){ui('dialog').querySelector('div').innerHTML='<b>Y.U.N.E.:</b> '+a+'<br><b>RESPOSTA:</b> '+b;ui('dialog').classList.add('show');dialogTime=360}
function hud(){ui('hptext').textContent=Math.max(0,Math.ceil(p.hp));ui('hpbar').style.width=Math.max(0,p.hp)+'%';ui('energytext').textContent=Math.floor(p.energy);ui('energybar').style.width=p.energy+'%';let z=zones.reduce((a,b)=>p.x>=b.x?b:a,zones[0]);ui('sector').textContent=z.n;ui('objective').textContent=boss.state==='awake'?'DERROTE SINE // '+Math.max(0,Math.ceil(boss.hp/boss.max*100))+'%':memories<3?'RECUPERE MEMÓRIAS　'+memories+' / 3':'ENCONTRE SINE // CATEDRAL';ui('dots').textContent=[0,1,2].map(i=>i<memories?'◆':'○').join('　');ui('memorytext').textContent='MEMÓRIAS INTACTAS';}
function mapDraw(){const el=ui('mapcontents'),px=p.x/WW*100;el.innerHTML='<div class="mapline"></div><div style="position:relative;height:70px;margin:24px 0 8px;background:linear-gradient(90deg,#37dec844,#a7ff7444,#ff4ca444);border:1px solid #ffffff22"><i style="position:absolute;left:'+px+'%;top:26px;color:#fff;font-style:normal;text-shadow:0 0 10px #62f5e3">▼ Y.U.N.E.</i>'+[650,2035,3820].map((v,i)=>'<b style="position:absolute;left:'+(v/WW*100)+'%;top:5px;color:'+(i<memories?'#ffcf74':'#ffffff77')+'">'+(i<memories?'◆':'◇')+'</b>').join('')+'</div><small style="color:#9bb2bb">0　SUBNÍVEIS　　1740　JARDINS　　3430　CATEDRAL　　5100</small>';}
function sfx(freq,dur,type='sine',vol=.03){if(!audio)return;try{let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch{}}
function music(){if(!audio)return;try{let o=audio.createOscillator(),g=audio.createGain(),l=audio.createOscillator(),lg=audio.createGain();o.type='triangle';o.frequency.value=55;l.frequency.value=.13;lg.gain.value=8;g.gain.value=.012;l.connect(lg);lg.connect(o.frequency);o.connect(g);g.connect(audio.destination);o.start();l.start()}catch{}}

